'use strict';
const names=['AI Resepsiyonist','AI Satışçı','AI Müşteri Temsilcisi','AI Teklif Uzmanı','AI CRM Asistanı','AI Satın Alma Asistanı','AI Muhasebe Asistanı','AI Yönetici Asistanı'];
const selected=new Set();
const options=document.querySelector('#role-options');
names.forEach((name,i)=>{const label=document.createElement('label');const input=document.createElement('input');input.type='checkbox';input.value=i;input.name='roles';input.addEventListener('change',()=>{input.checked?selected.add(i):selected.delete(i);sync();});label.append(input,document.createTextNode(name));options.append(label);});
function sync(){options.querySelectorAll('input').forEach(el=>el.checked=selected.has(Number(el.value)));document.querySelectorAll('.add-role').forEach(el=>{const chosen=selected.has(Number(el.dataset.role));el.setAttribute('aria-pressed',String(chosen));el.textContent=chosen?'✓':'↗';el.setAttribute('aria-label',names[Number(el.dataset.role)]+(chosen?' ekipten çıkar':' ekibime ekle'));});if(selected.size)document.querySelector('#selection-error').textContent='';}
document.querySelectorAll('.add-role').forEach(el=>el.addEventListener('click',()=>{const i=Number(el.dataset.role);selected.has(i)?selected.delete(i):selected.add(i);sync();}));
document.querySelectorAll('.package').forEach(el=>el.addEventListener('click',()=>{selected.clear();el.dataset.roles.split(',').forEach(i=>selected.add(Number(i)));sync();step(1,false);document.querySelector('#ekibini-kur').scrollIntoView({behavior:'smooth'});}));
document.querySelectorAll('[data-filter]').forEach(el=>el.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',String(b===el));});document.querySelectorAll('.employee').forEach(card=>card.hidden=el.dataset.filter!=='Tümü'&&card.dataset.category!==el.dataset.filter);}));
const menu=document.querySelector('#menu'),nav=document.querySelector('#navigation');function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');}menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});
function step(n,focus=true){[1,2,3].forEach(i=>document.querySelector('#step'+i).hidden=i!==n);document.querySelector('#step-label').textContent='0'+n+' / 03';if(focus){const target=document.querySelector('#step'+n+' input, #step'+n+' button');target?.focus({preventScroll:true});}}
document.querySelector('#next1').addEventListener('click',()=>{if(!selected.size){document.querySelector('#selection-error').textContent='Devam etmek için en az bir AI çalışan seçin.';return;}step(2);});
document.querySelector('#back1').addEventListener('click',()=>step(1));document.querySelector('#back2').addEventListener('click',()=>step(2));
let plan='';
document.querySelector('#next2').addEventListener('click',()=>{const fields=['company','sector','need'].map(id=>document.getElementById(id));for(const el of fields){el.setCustomValidity(el.value.trim()?'':'Lütfen bu alanı doldurun.');if(!el.reportValidity())return;}const [company,sector,need]=fields.map(el=>el.value.trim());const box=document.querySelector('#team-summary');box.replaceChildren();const heading=document.createElement('h3');heading.textContent=company;const sub=document.createElement('p');sub.textContent=sector;const list=document.createElement('ul');[...selected].sort().forEach(i=>{const li=document.createElement('li');li.textContent=names[i];list.append(li);});const text=document.createElement('p');text.textContent=need;box.append(heading,sub,list,text);plan='FuLab — AI Ekibi Başlangıç Planı\n\nİşletme: '+company+'\nSektör: '+sector+'\n\nSeçilen ekip:\n'+[...selected].sort().map(i=>'• '+names[i]).join('\n')+'\n\nİhtiyaç:\n'+need+'\n\nBu bir başlangıç planıdır. Talep gönderilmemiştir. Entegrasyon kapsamı ve fiyat ihtiyaç görüşmesinde belirlenir.';step(3);});
document.querySelectorAll('#step2 input,#step2 select,#step2 textarea').forEach(el=>el.addEventListener('input',()=>el.setCustomValidity('')));
document.querySelector('#team-form').addEventListener('submit',e=>e.preventDefault());
document.querySelector('#download').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([plan],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='fulab-ai-ekibim.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#download-status').textContent='Plan dosyanız hazırlandı. Henüz gönderim yapılmadı.';});
function dashboard(){const month=document.querySelector('#period').value==='month';['requests','tasks','pending','hours'].forEach((key,i)=>document.querySelector('#metric-'+key).textContent=(month?[1248,348,112,48]:[312,87,28,12])[i]);document.querySelector('#conversion-rate').textContent=month?'%28':'%24';const bars=document.querySelector('#bars');bars.replaceChildren();[8,14,22,32,45,58,73,94].forEach((height,i)=>{const bar=document.createElement('i');bar.style.height=(month?Math.min(height+8,100):height)+'%';bar.setAttribute('aria-hidden','true');bars.append(bar);});bars.setAttribute('aria-label','Örnek satış dönüşümü: '+(month?'yüzde 28':'yüzde 24'));}document.querySelector('#period').addEventListener('change',dashboard);dashboard();
(async()=>{const box=document.querySelector('#latest-posts');try{const response=await fetch('/ai-rehber/content.json');if(!response.ok)throw Error('Yayınlar alınamadı');const data=await response.json();const articles=data.articles.filter(a=>!a.status||a.status==='published').sort((a,b)=>(b.publishedAt||b.updatedAt).localeCompare(a.publishedAt||a.updatedAt)).slice(0,3);box.replaceChildren();if(!articles.length){box.textContent='Henüz yayın bulunmuyor.';return;}articles.forEach(a=>{const card=document.createElement('article');card.className='guide-card';const meta=document.createElement('div');const category=document.createElement('span');category.textContent=a.category;const date=document.createElement('time');date.dateTime=a.updatedAt;date.textContent=new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'short',year:'numeric'}).format(new Date(a.updatedAt+'T12:00:00'));meta.append(category,date);const h=document.createElement('h3');h.textContent=a.title;const p=document.createElement('p');p.textContent=a.description||a.summary;const link=document.createElement('a');link.className='text-link';link.href='/ai-rehber/?yazi='+encodeURIComponent(a.slug);link.textContent='Rehberi oku ↗';card.append(meta,h,p,link);box.append(card);});}catch{box.replaceChildren();const p=document.createElement('p');p.textContent='Son yayınlar şu anda yüklenemedi. ';const a=document.createElement('a');a.href='/ai-rehber/';a.textContent='AI Rehber’e git ↗';p.append(a);box.append(p);}})();

const shareStatus=document.querySelector('#download-status');
document.querySelector('#plan-whatsapp').addEventListener('click',e=>{e.currentTarget.href='https://wa.me/905512108080?text='+encodeURIComponent(plan);shareStatus.textContent='WhatsApp’ta mesajı kontrol edip Gönder’e basın. Henüz otomatik gönderim yapılmadı.';});
document.querySelector('#plan-email').addEventListener('click',e=>{e.currentTarget.href='mailto:fatih@fulabtr.net?subject='+encodeURIComponent('FuLab AI ekibi talebi')+'&body='+encodeURIComponent(plan);shareStatus.textContent='E-posta uygulamanızda gönderimi tamamlayabilirsiniz.';});
